-- Record complete official club crests from four current top-flight competitions,
-- then activate a balanced mixed pack of non-revealing organisation and club symbols.

-- GENERATED_FOOTBALL_CONTENT_START
on conflict (content_version, item_id) do update set
  display_name = excluded.display_name, asset_path = excluded.asset_path, reveal_asset_path = excluded.reveal_asset_path,
  asset_sha256 = excluded.asset_sha256, source_page_url = excluded.source_page_url, source_asset_url = excluded.source_asset_url,
  rights_status = excluded.rights_status, attribution = excluded.attribution, difficulty = excluded.difficulty, metadata = excluded.metadata;
-- GENERATED_FOOTBALL_CONTENT_END

update public.categories
set current_content_version = 'football-mixed-v3'
where id = 'football';

-- Rebuild only today's unplayed Football challenge. Attempts keep their
-- original immutable content version and round data.
delete from public.daily_challenges c
where c.category_id = 'football'
  and c.challenge_date = private.utc_today()
  and not exists (select 1 from public.daily_attempts a where a.challenge_id = c.id);

create or replace function private.quiz_options(p_content_version text, p_item_id text, p_seed text)
returns jsonb language sql volatile security definer set search_path = '' as $$
  with correct_item as (
    select item_id, display_name, metadata->>'scope' as scope,
      metadata->>'competitionKey' as competition_key
    from private.quiz_content
    where content_version = p_content_version and item_id = p_item_id
  ), distractors as (
    select q.item_id, q.display_name,
      case
        when q.metadata->>'scope' = c.scope
          and coalesce(q.metadata->>'competitionKey', '') = coalesce(c.competition_key, '') then 0
        when q.metadata->>'scope' = c.scope then 1
        else 2
      end as relevance_order
    from private.quiz_content q cross join correct_item c
    where q.content_version = p_content_version and q.item_id <> p_item_id
    order by relevance_order, md5(p_seed || ':' || q.item_id)
    limit 3
  ), picked as (
    select item_id, display_name from correct_item
    union all
    select item_id, display_name from distractors
  ), tokenized as (
    select item_id, display_name, extensions.gen_random_uuid() as choice_id
    from picked
  )
  select jsonb_build_object(
    'options', jsonb_agg(jsonb_build_object('id', choice_id, 'label', display_name)
      order by md5(p_seed || ':option:' || item_id)),
    'correctChoiceId', (array_agg(choice_id) filter (where item_id = p_item_id))[1]
  )
  from tokenized
$$;
